def compute(vars):
    restructuring_charges = vars["v1"]
    total_charges = vars["v2"]

    if total_charges == 0:
        return None

    ratio = restructuring_charges / total_charges
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "restructuring_charges": restructuring_charges,
            "total_goodwill_impairment_and_restructuring_charges": total_charges,
            "ratio": ratio,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
